// Patchline hosted worker (candidate route, not deployed): thin proxy host.
// - Serves the static UI (inlined at build time by scripts/build-worker.mjs).
// - Same timing-safe shared-secret gate as the local server on every /api route.
// - NEVER fetches user spec URLs itself and never runs the engines: interactive
//   work is dispatched to the GitHub Actions job workflow; heavy fetch/scan runs
//   on Actions where the $0 budget hard-block applies.
// - Job results are read back privately from the patchline-data branch via the
//   GitHub contents API, cached briefly in KV.
// Env bindings: PATCHLINE_AUTH_KEY (secret), GITHUB_DISPATCH_PAT (secret,
// repo-scoped Actions:write+Contents:read), GITHUB_REPO "owner/repo",
// GITHUB_API_BASE (default https://api.github.com), RATE_LIMIT_PER_HOUR
// (default 10), KV namespace JOBS.

const UI_HTML = /*__PATCHLINE_UI__*/"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Patchline - Self-maintaining API clients</title>\n<style>\n  :root {\n    --bg: #0a0e14; --panel: #11161f; --panel2: #151b26; --line: #232c3b;\n    --text: #e8edf4; --dim: #8b96a8; --faint: #5b6678;\n    --accent: #5eead4; --accent-dim: #134e4a;\n    --break: #f87171; --break-bg: #2a1518; --add: #4ade80; --add-bg: #12251a;\n    --warn: #fbbf24; --mono: \"SFMono-Regular\", ui-monospace, \"JetBrains Mono\", Menlo, Consolas, monospace;\n  }\n  * { box-sizing: border-box; margin: 0; padding: 0; }\n  body { background: var(--bg); color: var(--text); font: 15px/1.6 -apple-system, \"Inter\", \"Segoe UI\", Roboto, sans-serif; }\n  .wrap { max-width: 1080px; margin: 0 auto; padding: 0 28px 90px; }\n  header { padding: 44px 0 8px; display: flex; align-items: baseline; gap: 14px; }\n  .logo { font-size: 24px; font-weight: 700; letter-spacing: -0.4px; }\n  .logo span { color: var(--accent); }\n  .tag { color: var(--dim); font-size: 14px; }\n  .sub { color: var(--dim); max-width: 720px; margin: 10px 0 30px; font-size: 15px; }\n  .sub b { color: var(--text); font-weight: 600; }\n  nav.steps { display: flex; gap: 8px; margin: 26px 0 30px; flex-wrap: wrap; }\n  nav.steps button {\n    background: var(--panel); border: 1px solid var(--line); color: var(--dim);\n    padding: 10px 18px; border-radius: 10px; cursor: pointer; font-size: 14px; font-weight: 600;\n    transition: border-color .15s, color .15s;\n  }\n  nav.steps button .n { color: var(--faint); margin-right: 8px; font-family: var(--mono); font-size: 12px; }\n  nav.steps button.on { color: var(--text); border-color: var(--accent); background: var(--panel2); }\n  nav.steps button.on .n { color: var(--accent); }\n  nav.steps button:disabled { opacity: .45; cursor: not-allowed; }\n  section { display: none; }\n  section.on { display: block; animation: fade .25s ease; }\n  @keyframes fade { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }\n  .card { background: var(--panel); border: 1px solid var(--line); border-radius: 14px; padding: 24px; margin-bottom: 18px; }\n  .card h2 { font-size: 17px; font-weight: 700; margin-bottom: 6px; }\n  .card p.hint { color: var(--dim); font-size: 13.5px; margin-bottom: 16px; }\n  .grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }\n  @media (max-width: 860px) { .grid2 { grid-template-columns: 1fr; } }\n  label { display: block; font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; color: var(--faint); margin-bottom: 8px; }\n  textarea, select, input[type=text] {\n    width: 100%; background: var(--bg); border: 1px solid var(--line); color: var(--text);\n    border-radius: 10px; padding: 12px 14px; font-family: var(--mono); font-size: 12.5px; line-height: 1.5;\n  }\n  textarea { min-height: 220px; resize: vertical; }\n  textarea:focus, select:focus { outline: none; border-color: var(--accent); }\n  .btn {\n    background: var(--accent); color: #06201b; border: none; border-radius: 10px;\n    padding: 12px 22px; font-size: 14.5px; font-weight: 700; cursor: pointer; transition: filter .15s;\n  }\n  .btn:hover { filter: brightness(1.08); }\n  .btn.ghost { background: transparent; color: var(--dim); border: 1px solid var(--line); }\n  .btn.ghost:hover { color: var(--text); border-color: var(--dim); }\n  .row { display: flex; gap: 12px; align-items: center; margin-top: 18px; flex-wrap: wrap; }\n  .pill { display: inline-flex; align-items: center; gap: 6px; font-family: var(--mono); font-size: 11.5px; font-weight: 600; padding: 3px 10px; border-radius: 999px; }\n  .pill.break { background: var(--break-bg); color: var(--break); }\n  .pill.add { background: var(--add-bg); color: var(--add); }\n  .pill.warn { background: #2a2113; color: var(--warn); }\n  table { width: 100%; border-collapse: collapse; font-size: 13.5px; }\n  th { text-align: left; color: var(--faint); font-size: 11.5px; text-transform: uppercase; letter-spacing: .07em; padding: 10px 12px; border-bottom: 1px solid var(--line); }\n  td { padding: 12px; border-bottom: 1px solid var(--line); vertical-align: top; }\n  tr:last-child td { border-bottom: none; }\n  td code, .inline-code { font-family: var(--mono); font-size: 12px; background: var(--bg); padding: 2px 7px; border-radius: 6px; color: var(--accent); }\n  .mig { color: var(--dim); font-size: 12.5px; margin-top: 4px; }\n  .file-block { background: var(--bg); border: 1px solid var(--line); border-radius: 12px; margin-bottom: 16px; overflow: hidden; }\n  .file-head { display: flex; justify-content: space-between; align-items: center; padding: 10px 16px; background: var(--panel2); border-bottom: 1px solid var(--line); font-family: var(--mono); font-size: 12.5px; }\n  .file-head .counts { color: var(--faint); font-size: 11.5px; }\n  pre.diff { padding: 14px 16px; font-family: var(--mono); font-size: 12.5px; line-height: 1.65; overflow-x: auto; }\n  .diff .ctx { color: var(--faint); }\n  .diff .del { color: var(--break); background: rgba(248,113,113,.07); display: block; }\n  .diff .addline { color: var(--add); background: rgba(74,222,128,.07); display: block; }\n  .diff .meta { color: var(--warn); display: block; margin-top: 8px; }\n  .manual-item { padding: 10px 16px; border-top: 1px solid var(--line); font-size: 13px; color: var(--warn); }\n  .manual-item code { color: var(--text); }\n  pre.pr { background: var(--bg); border: 1px solid var(--line); border-radius: 12px; padding: 20px; font-family: var(--mono); font-size: 12.5px; line-height: 1.6; white-space: pre-wrap; max-height: 560px; overflow: auto; }\n  .stat-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-bottom: 18px; }\n  @media (max-width: 860px) { .stat-row { grid-template-columns: repeat(2, 1fr); } }\n  .urlrow { display: flex; gap: 8px; margin-bottom: 8px; }\n  .urlrow input { flex: 1; }\n  .urlrow .btn { padding: 8px 14px; font-size: 12.5px; }\n  .pill.review { background: #2a2113; color: var(--warn); }\n  .stat { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 16px 18px; }\n  .stat .v { font-size: 26px; font-weight: 700; font-family: var(--mono); }\n  .stat .k { color: var(--dim); font-size: 12px; margin-top: 2px; }\n  .stat.break .v { color: var(--break); } .stat.add .v { color: var(--add); } .stat.warn .v { color: var(--warn); }\n  footer { margin-top: 56px; padding-top: 22px; border-top: 1px solid var(--line); color: var(--faint); font-size: 12.5px; line-height: 1.7; }\n  .toast { position: fixed; bottom: 26px; left: 50%; transform: translateX(-50%); background: var(--panel2); border: 1px solid var(--accent); color: var(--accent); padding: 10px 20px; border-radius: 10px; font-size: 13.5px; opacity: 0; transition: opacity .2s; pointer-events: none; }\n  .toast.show { opacity: 1; }\n  body[data-mode=worker] .urlrow { display: none; }\n  body[data-mode=worker] #addWatchRow { display: none; }\n  body[data-mode=worker] #watchHintAuto { display: none; }\n  body[data-mode=worker] #watchHintManual { display: block; }\n</style>\n<script>\n// Shared-key gate client: when the server has PATCHLINE_AUTH_KEY set, every\n// /api call needs x-patchline-key. On a 401 an inline unlock overlay asks for\n// the key once; it is kept in sessionStorage (tab-local, never sent anywhere\n// except this server's /api routes).\n(() => {\n  const overlay = document.createElement('div');\n  overlay.id = 'unlockOverlay';\n  overlay.style.cssText = 'display:none;position:fixed;inset:0;background:rgba(10,12,16,.72);z-index:9999;align-items:center;justify-content:center;';\n  overlay.innerHTML = `\n    <div style=\"background:#161b22;border:1px solid #30363d;border-radius:10px;padding:24px;max-width:420px;width:90%;color:#e6edf3;font-family:inherit;\">\n      <h2 style=\"margin:0 0 8px;font-size:17px;\">This Patchline server is private</h2>\n      <p style=\"margin:0 0 14px;color:#9da7b3;font-size:13px;\">Enter the access key (the server was started with PATCHLINE_AUTH_KEY). The key stays in this tab's session storage only.</p>\n      <input id=\"unlockKey\" type=\"password\" placeholder=\"access key\" autocomplete=\"off\" style=\"width:100%;box-sizing:border-box;padding:9px 10px;border-radius:6px;border:1px solid #30363d;background:#0d1117;color:#e6edf3;font-size:14px;\" />\n      <div id=\"unlockError\" style=\"display:none;color:#f47067;font-size:13px;margin-top:8px;\">Wrong key - the server refused it. Try again.</div>\n      <button id=\"unlockGo\" style=\"margin-top:14px;padding:9px 18px;border-radius:6px;border:0;background:#238636;color:#fff;font-size:14px;cursor:pointer;\">Unlock</button>\n    </div>`;\n  document.addEventListener('DOMContentLoaded', () => document.body.appendChild(overlay));\n\n  let pending = null; // {url, opts, resolve}\n  const attempt = (url, opts) => {\n    const key = sessionStorage.getItem('patchline-key');\n    const o = Object.assign({}, opts);\n    if (key) o.headers = Object.assign({}, o.headers, { 'x-patchline-key': key });\n    return window.__origFetch(url, o);\n  };\n  window.__origFetch = window.fetch.bind(window);\n  window.fetch = (url, opts = {}) => {\n    // Static export mode: baked snapshot data, read-only. GET /api/watches and\n    // /api/events resolve from window.__PATCHLINE_STATIC__; everything else is\n    // refused with a clear message instead of silently failing.\n    if (window.__PATCHLINE_STATIC__ && typeof url === 'string' && url.startsWith('/api/')) {\n      const snap = window.__PATCHLINE_STATIC__;\n      const jsonRes = (code, body) => Promise.resolve(new Response(JSON.stringify(body), { status: code, headers: { 'content-type': 'application/json' } }));\n      if (url === '/api/health') return jsonRes(200, { ok: true, static: true, exportedAt: snap.exportedAt, watches: snap.watches.length, events: snap.events.length });\n      const m = (opts.method || 'GET').toUpperCase();\n      if (m === 'GET' && url === '/api/watches') return jsonRes(200, { watches: snap.watches, minIntervalMinutes: snap.minIntervalMinutes || 60 });\n      if (m === 'GET' && url === '/api/events') return jsonRes(200, { events: snap.events });\n      return jsonRes(501, { error: 'Static snapshot (read-only). Interactive features - adding watches, running checks, ad-hoc analysis - need the local server: npm start.' });\n    }\n    if (!(typeof url === 'string' && url.startsWith('/api/') && url !== '/api/health')) {\n      return window.__origFetch(url, opts);\n    }\n    return attempt(url, opts).then((res) => {\n      if (res.status !== 401) return res;\n      // show the unlock overlay and retry after a successful unlock\n      return new Promise((resolve) => { pending = { url, opts, resolve }; overlay.style.display = 'flex'; const inp = overlay.querySelector('#unlockKey'); if (inp) setTimeout(() => inp.focus(), 50); });\n    });\n  };\n  overlay.addEventListener('click', (e) => {\n    if (e.target && e.target.id === 'unlockGo') {\n      const key = overlay.querySelector('#unlockKey').value.trim();\n      if (!key || !pending) return;\n      sessionStorage.setItem('patchline-key', key);\n      attempt(pending.url, pending.opts).then((res) => {\n        if (res.status === 401) {\n          overlay.querySelector('#unlockError').style.display = 'block';\n          return; // keep overlay up\n        }\n        overlay.querySelector('#unlockError').style.display = 'none';\n        overlay.style.display = 'none';\n        const p = pending; pending = null;\n        p.resolve(res);\n      });\n    }\n  });\n  overlay.addEventListener('keydown', (e) => { if (e.key === 'Enter') overlay.querySelector('#unlockGo').click(); });\n})();</script>\n</head>\n<body>\n<div class=\"wrap\">\n  <header>\n    <div class=\"logo\">Patch<span>line</span></div>\n    <div class=\"tag\">Self-maintaining API clients</div>\n  </header>\n  <p class=\"sub\">An API provider ships a breaking change. Patchline diffs the old and new specs, flags affected call sites in the consumer codebase, and drafts the migration pull request - <b>deterministically, no AI inference</b>. It reads real OpenAPI 3.x documents (YAML or JSON, local $refs resolved) and can watch a live spec URL for changes. The sample below is a fictional billing API.</p>\n\n  <nav class=\"steps\">\n    <button data-step=\"1\" class=\"on\"><span class=\"n\">01</span>Specs</button>\n    <button data-step=\"2\" disabled><span class=\"n\">02</span>API diff</button>\n    <button data-step=\"3\" disabled><span class=\"n\">03</span>Consumer impact</button>\n    <button data-step=\"4\" disabled><span class=\"n\">04</span>Fix PR</button>\n    <button data-step=\"5\" id=\"watchTab\" style=\"display:none\"><span class=\"n\">05</span>Watch</button>\n  </nav>\n\n  <section id=\"s1\" class=\"on\">\n    <div class=\"card\">\n      <h2>Choose the spec pair</h2>\n      <p class=\"hint\">The sample pair is the fictional <b>Northwind Billing API v1.8.1 &rarr; v2.0.0</b>. Paste any <b>OpenAPI 3.x spec (YAML or JSON)</b> - Local <code>$ref</code>s, request bodies and content-wrapped schemas are resolved. <span id=\"modeNote\"></span></p>\n      <div class=\"grid2\">\n        <div>\n          <label>Old spec - <span id=\"oldVerLabel\"></span></label>\n          <div class=\"urlrow\"><input type=\"text\" id=\"oldUrl\" placeholder=\"https://.../openapi.yaml\"><button class=\"btn ghost\" id=\"loadOldUrl\">Load URL</button></div>\n          <textarea id=\"oldSpec\" spellcheck=\"false\"></textarea>\n        </div>\n        <div>\n          <label>New spec - <span id=\"newVerLabel\"></span></label>\n          <div class=\"urlrow\"><input type=\"text\" id=\"newUrl\" placeholder=\"https://.../openapi.yaml\"><button class=\"btn ghost\" id=\"loadNewUrl\">Load URL</button></div>\n          <textarea id=\"newSpec\" spellcheck=\"false\"></textarea>\n        </div>\n      </div>\n      <div class=\"row\">\n        <button class=\"btn\" id=\"runDiff\">Run the diff</button>\n        <button class=\"btn ghost\" id=\"resetSpecs\">Reset to sample</button>\n        <span id=\"specError\" style=\"color:var(--break);font-size:13px\"></span>\n      </div>\n      <div id=\"hostedBox\" style=\"display:none;margin-top:22px;border-top:1px solid var(--line);padding-top:18px\">\n        <h2 style=\"font-size:15px;margin-bottom:6px\">Hosted analysis (background job)</h2>\n        <p class=\"hint\">Give two public spec URLs and optionally a consumer GitHub repo. Fetching and the repo scan run as a background job on this deployment's pipeline; the result renders in steps 02-04. The access key is asked once when the server needs it and stays in this tab only.</p>\n        <div class=\"grid2\">\n          <div><label>Old spec URL</label><input type=\"text\" id=\"jobOldUrl\" placeholder=\"https://.../openapi.yaml\"></div>\n          <div><label>New spec URL</label><input type=\"text\" id=\"jobNewUrl\" placeholder=\"https://.../openapi.yaml\"></div>\n        </div>\n        <div style=\"margin-top:12px\"><label>Consumer repo (optional, GitHub)</label><input type=\"text\" id=\"jobRepoUrl\" placeholder=\"https://github.com/owner/repo\"></div>\n        <div class=\"row\">\n          <button class=\"btn\" id=\"runJob\">Run hosted analysis</button>\n          <span id=\"jobStatus\" style=\"font-size:13px;color:var(--dim)\"></span>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"s2\">\n    <div class=\"stat-row\" id=\"statRow\"></div>\n    <div class=\"card\">\n      <h2>Detected changes</h2>\n      <p class=\"hint\">Rule-based classification: removed endpoints and renamed fields are breaking; new endpoints and optional fields are additive.</p>\n      <table id=\"changeTable\"><thead><tr><th style=\"width:90px\">Kind</th><th style=\"width:190px\">Type</th><th>Detail</th></tr></thead><tbody></tbody></table>\n    </div>\n    <div class=\"row\"><button class=\"btn\" id=\"toImpact\">Scan the consumer codebase</button></div>\n  </section>\n\n  <section id=\"s3\">\n    <div class=\"card\">\n      <h2>Consumer codebase impact</h2>\n      <p class=\"hint\">The sample consumer is a 4-file JS app calling the old API. Patchline flags lines matching the detected breaking-change patterns and proposes safe mechanical edits. Removed endpoints are never auto-rewritten - they are flagged for manual review.</p>\n      <div id=\"impactList\"></div>\n    </div>\n    <div class=\"row\">\n      <label style=\"display:flex;align-items:center;gap:8px;text-transform:none;letter-spacing:0;font-size:13px;color:var(--dim)\"><input type=\"checkbox\" id=\"applyInferred\" style=\"width:auto\"> Apply inferred rename/enum suggestions (guesses - verify first)</label>\n      <button class=\"btn\" id=\"toPR\">Prepare the migration PR draft</button>\n    </div>\n  </section>\n\n  <section id=\"s4\">\n    <div class=\"card\">\n      <h2>Draft pull request</h2>\n      <p class=\"hint\">A prepared draft only - Patchline never opens or sends PRs. A human reviews this markdown, applies the branch, and files the PR.</p>\n      <pre class=\"pr\" id=\"prOut\"></pre>\n      <div class=\"row\">\n        <button class=\"btn\" id=\"copyPR\">Copy PR markdown</button>\n        <button class=\"btn ghost\" id=\"dlPR\">Download .md</button>\n        <button class=\"btn ghost\" id=\"dlJSON\">Download analysis .json</button>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"s5\">\n    <div class=\"card\">\n      <h2>Watch a live API spec</h2>\n      <p class=\"hint\" id=\"watchHintAuto\">Patchline polls the spec URL on the interval you set (minimum <span id=\"minInt\">60</span> minutes, with conditional requests so unchanged specs cost one cheap 304), saves a baseline, and records a diff event whenever the served spec actually changes.</p>\n      <p class=\"hint\" id=\"watchHintManual\" style=\"display:none\">On this hosted deployment there is no automated watching - each check is a manual hosted analysis (step 01). Automated polling runs with the local server or the self-hosted GitHub Actions schedule.</p>\n      <div class=\"row\" id=\"addWatchRow\" style=\"margin-top:0;margin-bottom:14px\">\n        <input type=\"text\" id=\"wName\" placeholder=\"Name (e.g. Acme Payments)\" style=\"max-width:240px\">\n        <input type=\"text\" id=\"wUrl\" placeholder=\"https://.../openapi.yaml\" style=\"max-width:340px\">\n        <input type=\"text\" id=\"wInt\" placeholder=\"Minutes\" style=\"max-width:100px\">\n        <button class=\"btn\" id=\"addWatch\">Add watch</button>\n      </div>\n      <div id=\"watchError\" style=\"color:var(--break);font-size:13px;margin-bottom:10px\"></div>\n      <table id=\"watchTable\"><thead><tr><th>Name</th><th>URL</th><th style=\"width:90px\">Interval</th><th style=\"width:170px\">Last check</th><th>Result</th><th style=\"width:150px\"></th></tr></thead><tbody></tbody></table>\n    </div>\n    <div class=\"card\">\n      <h2>Change events</h2>\n      <p class=\"hint\">Recorded when a watched spec actually changes. Each event is the full breaking/additive/warning diff between the old snapshot and the new one.</p>\n      <div id=\"eventList\"></div>\n    </div>\n  </section>\n\n  <footer>\n    Patchline &middot; fictional sample API and consumer app &middot; all analysis is deterministic rules over the specs you provide - no AI inference &middot; in hosted mode, specs you load by URL are processed by this server (no automated watching) &middot; detection tools like oasdiff already exist - the wedge here is the <i>application</i> layer: scanning consumer code and drafting the fix.<br>\n    Built for the YC Fall 2026 RFS idea \"Self-Maintaining APIs\". A YC request signals partner interest, not validated demand.\n  </footer>\n</div>\n<div class=\"toast\" id=\"toast\"></div>\n\n<script id=\"fixtures\" type=\"application/json\">{\"oldSpec\": {\"openapi\": \"3.0.0\", \"info\": {\"title\": \"Northwind Billing API\", \"version\": \"1.8.1\"}, \"paths\": {\"/v1/invoices\": {\"get\": {\"operationId\": \"listInvoices\", \"parameters\": [{\"name\": \"limit\", \"in\": \"query\", \"required\": false, \"schema\": {\"type\": \"integer\"}}, {\"name\": \"status\", \"in\": \"query\", \"required\": false, \"schema\": {\"type\": \"string\", \"enum\": [\"draft\", \"pending\", \"paid\", \"void\"]}}], \"responses\": {\"200\": {\"description\": \"OK\", \"schema\": {\"type\": \"object\", \"properties\": {\"invoices\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"properties\": {\"id\": {\"type\": \"string\"}, \"amount_cents\": {\"type\": \"integer\"}, \"status\": {\"type\": \"string\", \"enum\": [\"draft\", \"pending\", \"paid\", \"void\"]}, \"customer_email\": {\"type\": \"string\"}}, \"required\": [\"id\", \"amount_cents\", \"status\"]}}}, \"required\": [\"invoices\"]}}}}, \"post\": {\"operationId\": \"createInvoice\", \"parameters\": [], \"requestSchema\": {\"type\": \"object\", \"properties\": {\"customer_email\": {\"type\": \"string\"}, \"amount_cents\": {\"type\": \"integer\"}}, \"required\": [\"customer_email\", \"amount_cents\"]}, \"responses\": {\"201\": {\"description\": \"Created\", \"schema\": {\"type\": \"object\", \"properties\": {\"id\": {\"type\": \"string\"}, \"amount_cents\": {\"type\": \"integer\"}, \"status\": {\"type\": \"string\"}}, \"required\": [\"id\", \"amount_cents\", \"status\"]}}}}}, \"/v1/charges\": {\"post\": {\"operationId\": \"createCharge\", \"parameters\": [], \"requestSchema\": {\"type\": \"object\", \"properties\": {\"card_token\": {\"type\": \"string\"}, \"amount_cents\": {\"type\": \"integer\"}}, \"required\": [\"card_token\", \"amount_cents\"]}, \"responses\": {\"201\": {\"description\": \"Created\", \"schema\": {\"type\": \"object\", \"properties\": {\"id\": {\"type\": \"string\"}, \"status\": {\"type\": \"string\"}}, \"required\": [\"id\", \"status\"]}}}}}}}, \"newSpec\": {\"openapi\": \"3.0.0\", \"info\": {\"title\": \"Northwind Billing API\", \"version\": \"2.0.0\"}, \"paths\": {\"/v2/invoices\": {\"get\": {\"operationId\": \"listInvoices\", \"parameters\": [{\"name\": \"page_size\", \"in\": \"query\", \"required\": false, \"schema\": {\"type\": \"integer\"}}, {\"name\": \"status\", \"in\": \"query\", \"required\": false, \"schema\": {\"type\": \"string\", \"enum\": [\"draft\", \"open\", \"paid\", \"void\"]}}], \"responses\": {\"200\": {\"description\": \"OK\", \"schema\": {\"type\": \"object\", \"properties\": {\"invoices\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"properties\": {\"id\": {\"type\": \"string\"}, \"total_cents\": {\"type\": \"integer\"}, \"status\": {\"type\": \"string\", \"enum\": [\"draft\", \"open\", \"paid\", \"void\"]}, \"customer_email\": {\"type\": \"string\"}}, \"required\": [\"id\", \"total_cents\", \"status\"]}}}, \"required\": [\"invoices\"]}}}}, \"post\": {\"operationId\": \"createInvoice\", \"parameters\": [], \"requestSchema\": {\"type\": \"object\", \"properties\": {\"customer_email\": {\"type\": \"string\"}, \"total_cents\": {\"type\": \"integer\"}}, \"required\": [\"customer_email\", \"total_cents\"]}, \"responses\": {\"201\": {\"description\": \"Created\", \"schema\": {\"type\": \"object\", \"properties\": {\"id\": {\"type\": \"string\"}, \"total_cents\": {\"type\": \"integer\"}, \"status\": {\"type\": \"string\"}}, \"required\": [\"id\", \"total_cents\", \"status\"]}}}}}, \"/v2/customers/{id}/balance\": {\"get\": {\"operationId\": \"getCustomerBalance\", \"parameters\": [{\"name\": \"id\", \"in\": \"path\", \"required\": true, \"schema\": {\"type\": \"string\"}}], \"responses\": {\"200\": {\"description\": \"OK\", \"schema\": {\"type\": \"object\", \"properties\": {\"balance_cents\": {\"type\": \"integer\"}}, \"required\": [\"balance_cents\"]}}}}}}}, \"consumer\": [{\"name\": \"charges.js\", \"content\": \"import { api } from './client.js';\\n\\n// Charge a card token directly\\nexport async function chargeCard(cardToken, amountCents) {\\n  const res = await api.post('/v1/charges', { card_token: cardToken, amount_cents: amountCents });\\n  return res.status === 'succeeded';\\n}\\n\"}, {\"name\": \"client.js\", \"content\": \"// Thin wrapper around fetch for the Northwind Billing API\\nexport const api = {\\n  base: 'https://api.northwind.example',\\n  async get(path, opts = {}) {\\n    const q = opts.params ? '?' + new URLSearchParams(opts.params) : '';\\n    const r = await fetch(this.base + path + q, { headers: this.headers() });\\n    return r.json();\\n  },\\n  async post(path, body) {\\n    const r = await fetch(this.base + path, { method: 'POST', headers: this.headers(), body: JSON.stringify(body) });\\n    return r.json();\\n  },\\n  headers() { return { 'Authorization': 'Bearer ' + process.env.NORTHWIND_KEY, 'Content-Type': 'application/json' }; },\\n};\\n\"}, {\"name\": \"dashboard.js\", \"content\": \"import { listPendingInvoices } from './invoices.js';\\n\\nexport async function renderDashboard() {\\n  const rows = await listPendingInvoices();\\n  for (const row of rows) {\\n    console.log(`Invoice ${row.id}: ${row.total} (${row.state})`);\\n  }\\n}\\n\"}, {\"name\": \"invoices.js\", \"content\": \"import { api } from './client.js';\\n\\n// List recent pending invoices for the dashboard\\nexport async function listPendingInvoices() {\\n  const res = await api.get('/v1/invoices', { params: { limit: 20, status: 'pending' } });\\n  return res.invoices.map((inv) => ({\\n    id: inv.id,\\n    total: inv.amount_cents / 100,\\n    state: inv.status,\\n  }));\\n}\\n\\nexport async function createInvoice(email, amountCents) {\\n  const res = await api.post('/v1/invoices', { customer_email: email, amount_cents: amountCents });\\n  return res.id;\\n}\\n\"}]}</script>\n<script>\n\"use strict\";\n// Patchline deterministic engines: spec diff, consumer impact scan, fix + PR generation.\n// No network, no AI inference. All logic is rule-based and testable.\n\nconst VERSION_PREFIX = /^\\/v\\d+/;\n\nfunction normalizePath(p) {\n  return p.replace(VERSION_PREFIX, '');\n}\n\nfunction leafName(fieldPath) {\n  // code refers to the leaf: \"invoices[].total.amount_cents\" -> \"amount_cents\"\n  if (!fieldPath) return fieldPath;\n  return fieldPath.replace(/\\[\\]/g, '').split('.').pop();\n}\n\nfunction endpointContext(changePath) {\n  // \"GET /v2/invoices/{id}\" -> \"/invoices/\" (normalized, no version prefix, no params)\n  if (!changePath) return null;\n  const p = changePath.includes(' ') ? changePath.split(' ')[1] : changePath;\n  if (!p) return null;\n  return normalizePath(p).replace(/\\{[^}]+\\}/g, '') || null;\n}\n\n// Paths this file actually calls, among the endpoints involved in the change set.\n// A file mentioning specific endpoints should only match their field/param changes;\n// a file mentioning none stays eligible (honest uncertainty beats a false clean).\nfunction fileEndpointSet(content, allPaths) {\n  const found = new Set();\n  for (const p of allPaths) if (p && content.includes(p)) found.add(p);\n  return found;\n}\n\nfunction flattenSpec(spec) {\n  const out = new Map();\n  const paths = spec.paths || {};\n  for (const [p, methods] of Object.entries(paths)) {\n    for (const [m, op] of Object.entries(methods)) {\n      const resp = op.responses || {};\n      const successCodes = Object.keys(resp).filter((c) => /^2\\d\\d$/.test(c)).sort();\n      const first = resp['200'] || resp['201'] || (successCodes[0] && resp[successCodes[0]]) || Object.values(resp)[0] || {};\n      const fields = {};\n      const props = first.schema?.properties || {};\n      // one level of array items / object properties is enough for the demo scope\n      const collect = (properties, prefix, requiredList) => {\n        for (const [name, def] of Object.entries(properties || {})) {\n          fields[prefix + name] = {\n            type: def.type || 'object',\n            required: (requiredList || []).includes(name),\n            enum: def.enum || null,\n          };\n          if (def.type === 'array' && def.items?.properties) {\n            collect(def.items.properties, prefix + name + '[].', def.items.required);\n          } else if ((def.type === 'object' || !def.type) && def.properties) {\n            collect(def.properties, prefix + name + '.', def.required);\n          }\n        }\n      };\n      collect(props, '', first.schema?.required);\n      const reqProps = op.requestSchema?.properties || {};\n      const requestFields = {};\n      for (const [name, def] of Object.entries(reqProps)) {\n        requestFields[name] = { type: def.type || 'object', required: (op.requestSchema?.required || []).includes(name) };\n      }\n      out.set(`${m.toUpperCase()} ${p}`, {\n        method: m.toUpperCase(),\n        path: p,\n        deprecated: !!op.deprecated,\n        responseCodes: Object.keys(resp),\n        security: op.security !== undefined && op.security !== null ? op.security : (spec._securityDefault || []),\n        normalized: normalizePath(p),\n        operationId: op.operationId || null,\n        params: (op.parameters || []).map((x) => ({ name: x.name, location: x.in, required: !!x.required, type: x.schema?.type || 'string', enum: x.schema?.enum || null })),\n        responseFields: fields,\n        requestFields,\n      });\n    }\n  }\n  return out;\n}\n\nfunction renameCandidate(oldFields, newFields) {\n  // A rename is an INFERENCE, not a fact: pair a removed field with an added\n  // field only when the match is unambiguous both directions (exactly one\n  // type-compatible partner on each side). Ambiguous cases stay separate\n  // removed/added entries - a wrong rename guess silently corrupts data.\n  const removed = Object.keys(oldFields).filter((k) => !(k in newFields));\n  const added = Object.keys(newFields).filter((k) => !(k in oldFields));\n  const pairs = [];\n  const usedAdded = new Set();\n  const parentOf = (k) => k.includes('.') ? k.slice(0, k.lastIndexOf('.') + 1) : '';\n  for (const r of removed) {\n    let cands = added.filter((a) => !usedAdded.has(a) && newFields[a].type === oldFields[r].type);\n    // a renamed field normally stays in the same object - same-parent matches win\n    const sameParent = cands.filter((a) => parentOf(a) === parentOf(r));\n    if (sameParent.length) cands = sameParent;\n    if (cands.length !== 1) continue;\n    const reverse = removed.filter((x) => x !== r && !pairs.some(([pr]) => pr === x) && oldFields[x].type === newFields[cands[0]].type && parentOf(x) === parentOf(cands[0]));\n    if (reverse.length > 0) continue;\n    pairs.push([r, cands[0]]);\n    usedAdded.add(cands[0]);\n  }\n  return { pairs, removedOnly: removed.filter((r) => !pairs.some(([a]) => a === r)), addedOnly: added.filter((a) => !usedAdded.has(a)) };\n}\n\n\nconst leafOf = (k) => (k || '').split('.').pop();\nfunction collisionLeaves(...fieldSets) {\n  const s = new Set();\n  for (const fs of fieldSets) for (const k of Object.keys(fs || {})) s.add(leafOf(k));\n  return s;\n}\n// A rename pair whose \"from\" leaf also names a field on the other side of\n// the operation (request vs response) is ambiguous in consumer text - a read\n// looks like a write. Suppress it UNLESS the other side pairs the same leaf\n// to the same target (a consistent cross-side rename is position-safe).\nfunction suppressCrossSideAmbiguity(result, otherSideLeaves, otherPairMap) {\n  const keep = [], demoted = [];\n  for (const [a, b] of result.pairs) {\n    const la = leafOf(a);\n    if (otherSideLeaves.has(la) && otherPairMap.get(la) !== leafOf(b)) demoted.push([a, b]);\n    else keep.push([a, b]);\n  }\n  if (!demoted.length) return result;\n  return {\n    pairs: keep,\n    removedOnly: [...result.removedOnly, ...demoted.map(([a]) => a)],\n    addedOnly: [...result.addedOnly, ...demoted.map(([, b]) => b)],\n  };\n}\nconst leafPairMap = (pairs) => new Map(pairs.map(([a, b]) => [leafOf(a), leafOf(b)]));\n\nfunction diffSpecs(oldSpec, newSpec) {\n  const oldMap = flattenSpec(oldSpec);\n  const newMap = flattenSpec(newSpec);\n  const changes = [];\n  // every endpoint in either spec: lets consumer scoping recognize a file that\n  // calls a DIFFERENT known endpoint and keep it out of this diff's field hits\n  changes.allEndpoints = [...new Set([...oldMap.keys(), ...newMap.keys()].map((k) => endpointContext(k)).filter(Boolean))];\n  const matched = new Set();\n\n  // match endpoints across version prefixes\n  const newByNormalized = new Map();\n  for (const [key, ep] of newMap) {\n    const nk = `${ep.method} ${ep.normalized}`;\n    if (!newByNormalized.has(nk)) newByNormalized.set(nk, []);\n    newByNormalized.get(nk).push([key, ep]);\n  }\n\n  for (const [key, ep] of oldMap) {\n    const nk = `${ep.method} ${ep.normalized}`;\n    const candidates = (newByNormalized.get(nk) || []).filter(([k]) => !matched.has(k));\n    if (candidates.length === 0) {\n      changes.push({ kind: 'breaking', type: 'endpoint_removed', endpoint: key, detail: `${key} no longer exists in v${newSpec.info.version}.`, migration: 'Manual review: no direct replacement. Check whether another endpoint covers this workflow.' });\n      continue;\n    }\n    const [newKey, nep] = candidates[0];\n    matched.add(newKey);\n    if (!ep.deprecated && nep.deprecated) {\n      changes.push({ kind: 'warning', type: 'endpoint_deprecated', endpoint: key, detail: `${newKey} is now marked deprecated in v${newSpec.info.version}.`, migration: 'Plan a move off this endpoint before its sunset; no immediate breakage.', from: key, to: null });\n    }\n    const oldCodes = (ep.responseCodes || []).filter((c) => /^2\\d\\d$/.test(c));\n    const newCodes = new Set((nep.responseCodes || []).filter((c) => /^2\\d\\d$/.test(c)));\n    for (const code of oldCodes) {\n      if (!newCodes.has(code)) {\n        changes.push({ kind: 'breaking', type: 'response_code_removed', endpoint: key, detail: `${key} no longer returns HTTP ${code}.`, migration: 'Manual review: check whether clients branch on this status code and what replaced it.', from: code, to: null });\n      }\n    }\n    if (JSON.stringify(ep.security || []) !== JSON.stringify(nep.security || [])) {\n      changes.push({ kind: 'breaking', type: 'security_changed', endpoint: key, detail: `Authentication requirements changed on ${newKey}.`, migration: 'Manual review: compare old and new security requirements and update client credentials/scopes.', from: null, to: null });\n    }\n    if (ep.path !== nep.path) {\n      changes.push({ kind: 'breaking', type: 'base_path_changed', endpoint: key, detail: `Base path moved ${ep.path} -> ${nep.path}.`, migration: `Replace URL prefix ${ep.path.match(VERSION_PREFIX)?.[0] || ''} with ${nep.path.match(VERSION_PREFIX)?.[0] || ''}.`, from: ep.path, to: nep.path });\n    }\n    // params\n    const oldP = Object.fromEntries(ep.params.map((x) => [x.name, x]));\n    const newP = Object.fromEntries(nep.params.map((x) => [x.name, x]));\n    const prRaw = renameCandidate(\n      Object.fromEntries(ep.params.map((x) => [x.name, { type: x.type }])),\n      Object.fromEntries(nep.params.map((x) => [x.name, { type: x.type }]))\n    );\n    const frRaw = renameCandidate(ep.responseFields, nep.responseFields);\n    const qrRaw = renameCandidate(ep.requestFields, nep.requestFields);\n    // param renames share consumer text with body fields: a param leaf that\n    // also names a request/response field is ambiguous unless a body pair\n    // maps the same leaf to the same target. Ambiguous -> manual review.\n    const bodyPairMap = new Map([...leafPairMap(frRaw.pairs), ...leafPairMap(qrRaw.pairs)]);\n    const bodyLeaves = collisionLeaves(ep.requestFields, nep.requestFields, ep.responseFields, nep.responseFields);\n    const pr = suppressCrossSideAmbiguity(prRaw, bodyLeaves, bodyPairMap);\n    const prDemotedAdded = pr.addedOnly.filter((a) => !prRaw.addedOnly.includes(a));\n    for (const [a, b] of pr.pairs) {\n      changes.push({ kind: 'breaking', type: 'param_renamed', endpoint: key, detail: `Query parameter \"${a}\" appears renamed to \"${b}\" on ${newKey} (inferred, verify).`, migration: `Suggested: rename \"${a}\" to \"${b}\" at call sites (inferred - confirm before applying).`, from: a, to: b, inferred: true });\n    }\n    for (const r of pr.removedOnly) {\n      changes.push({ kind: 'breaking', type: 'param_removed', endpoint: key, detail: `Parameter \"${r}\" was removed from ${key}.`, migration: 'Remove the parameter or map it to new behavior manually.', from: r, to: null });\n    }\n    for (const a of prDemotedAdded) {\n      changes.push({ kind: 'breaking', type: 'param_added', endpoint: key, detail: `Parameter \"${a}\" is new on ${newKey} and may be an ambiguous rename (its name collides with a body field) - manual review.`, migration: 'Manual review: text matching cannot distinguish this parameter from the same-named body field; confirm any rename by hand.', from: null, to: a });\n    }\n    // same-name params: required flip and type change\n    for (const [name, op_] of Object.entries(oldP)) {\n      const np_ = newP[name];\n      if (!np_) continue;\n      if (!op_.required && np_.required) {\n        changes.push({ kind: 'breaking', type: 'param_required_changed', endpoint: key, detail: `Parameter \"${name}\" on ${newKey} is now required.`, migration: `Pass \"${name}\" at every call site of this endpoint.`, from: name, to: null });\n      }\n      if (op_.type && np_.type && op_.type !== np_.type) {\n        changes.push({ kind: 'breaking', type: 'param_type_changed', endpoint: key, detail: `Parameter \"${name}\" type changed ${op_.type} -> ${np_.type} on ${newKey}.`, migration: 'Manual review: update values sent for this parameter to the new type.', from: op_.type, to: np_.type, param: name });\n      }\n    }\n    // enum values on params retained by name\n    for (const [name, op_] of Object.entries(oldP)) {\n      const np_ = newP[name];\n      if (np_ && op_.enum && np_.enum) {\n        const lost = op_.enum.filter((v) => !np_.enum.includes(v));\n        const gained = np_.enum.filter((v) => !op_.enum.includes(v));\n        for (const v of lost) {\n          const guess = gained.length === 1 ? gained[0] : null;\n          changes.push({ kind: 'breaking', type: 'enum_value_removed', endpoint: key, detail: `\"${name}\" value \"${v}\" was removed${guess ? ` (new value \"${guess}\" may replace it - inferred, verify)` : ''}.`, migration: guess ? `Suggested: replace \"${v}\" with \"${guess}\" (inferred - confirm before applying).` : 'Choose a supported value manually.', from: v, to: guess, param: name, inferred: !!guess });\n        }\n      }\n    }\n    // response fields\n    const fr = suppressCrossSideAmbiguity(frRaw, collisionLeaves(ep.requestFields, nep.requestFields), leafPairMap(qrRaw.pairs));\n    for (const [a, b] of fr.pairs) {\n      changes.push({ kind: 'breaking', type: 'response_field_renamed', endpoint: key, detail: `Response field \"${a}\" appears renamed to \"${b}\" on ${newKey} (inferred, verify).`, migration: `Suggested: rename reads of \"${a}\" to \"${b}\" (inferred - confirm before applying).`, from: a, to: b, inferred: true });\n    }\n    for (const r of fr.removedOnly) {\n      changes.push({ kind: 'breaking', type: 'response_field_removed', endpoint: key, detail: `Response field \"${r}\" was removed from ${key}.`, migration: 'Stop reading this field or source it elsewhere.', from: r, to: null });\n    }\n    for (const a of fr.addedOnly) {\n      changes.push({ kind: 'additive', type: 'response_field_added', endpoint: newKey, detail: `New response field \"${a}\" on ${newKey}.`, migration: 'Optional: adopt when useful.', from: null, to: a });\n    }\n    // response fields retained by name: type changes\n    for (const [name, of_] of Object.entries(ep.responseFields)) {\n      const nf_ = nep.responseFields[name];\n      if (nf_ && of_.type && nf_.type && of_.type !== nf_.type) {\n        changes.push({ kind: 'breaking', type: 'response_field_type_changed', endpoint: key, detail: `Response field \"${name}\" type changed ${of_.type} -> ${nf_.type} on ${newKey}.`, migration: 'Manual review: update code that reads this field to handle the new type.', from: of_.type, to: nf_.type, field: name });\n      }\n    }\n    // request fields\n    const qr = suppressCrossSideAmbiguity(qrRaw, collisionLeaves(ep.responseFields, nep.responseFields), leafPairMap(frRaw.pairs));\n    for (const [a, b] of qr.pairs) {\n      changes.push({ kind: 'breaking', type: 'request_field_renamed', endpoint: key, detail: `Request field \"${a}\" appears renamed to \"${b}\" on ${newKey} (inferred, verify).`, migration: `Suggested: rename writes of \"${a}\" to \"${b}\" (inferred - confirm before applying).`, from: a, to: b, inferred: true });\n    }\n    for (const r of qr.removedOnly) {\n      changes.push({ kind: 'breaking', type: 'request_field_removed', endpoint: key, detail: `Request field \"${r}\" was removed from ${key}.`, migration: 'Manual review: stop sending this field; check whether the API now rejects or ignores it.', from: r, to: null });\n    }\n    for (const a of qr.addedOnly) {\n      const req = nep.requestFields[a]?.required;\n      changes.push(req\n        ? { kind: 'breaking', type: 'request_field_added_required', endpoint: key, detail: `New required request field \"${a}\" on ${newKey}.`, migration: 'Manual review: every call to this endpoint must now send a valid value for this field.', from: null, to: a }\n        : { kind: 'additive', type: 'request_field_added', endpoint: newKey, detail: `New optional request field \"${a}\" on ${newKey}.`, migration: 'Optional: adopt when useful.', from: null, to: a });\n    }\n    // request fields retained by name: type changes\n    for (const [name, of_] of Object.entries(ep.requestFields)) {\n      const nf_ = nep.requestFields[name];\n      if (nf_ && of_.type && nf_.type && of_.type !== nf_.type) {\n        changes.push({ kind: 'breaking', type: 'request_field_type_changed', endpoint: key, detail: `Request field \"${name}\" type changed ${of_.type} -> ${nf_.type} on ${newKey}.`, migration: 'Manual review: update code that writes this field to send the new type.', from: of_.type, to: nf_.type, field: name });\n      }\n    }\n    // response enum changes\n    for (const [name, of] of Object.entries(ep.responseFields)) {\n      const nf = nep.responseFields[name];\n      if (nf && of.enum && nf.enum) {\n        const lost = of.enum.filter((v) => !nf.enum.includes(v));\n        const gained = nf.enum.filter((v) => !of.enum.includes(v));\n        for (const v of lost) {\n          const guess = gained.length === 1 ? gained[0] : null;\n          changes.push({ kind: 'breaking', type: 'enum_value_removed', endpoint: key, detail: `Response field \"${name}\" value \"${v}\" was removed${guess ? ` (new value \"${guess}\" may replace it - inferred, verify)` : ''}.`, migration: guess ? `Suggested: map \"${v}\" to \"${guess}\" (inferred - confirm before applying).` : 'Map manually to a supported value.', from: v, to: guess, field: name, inferred: !!guess });\n        }\n      }\n    }\n  }\n  // doc-level security schemes removed\n  const oldSchemes = Object.keys(oldSpec._securitySchemes || {});\n  const newSchemes = new Set(Object.keys(newSpec._securitySchemes || {}));\n  for (const s of oldSchemes) {\n    if (!newSchemes.has(s)) {\n      changes.push({ kind: 'breaking', type: 'security_scheme_removed', endpoint: '(document)', detail: `Security scheme \"${s}\" was removed.`, migration: 'Manual review: clients authenticating with this scheme must move to a supported one.', from: s, to: null });\n    }\n  }\n  // endpoints only in new spec\n  for (const [key, ep] of newMap) {\n    if (!matched.has(key)) {\n      const wasMatchedAsPair = [...oldMap.values()].some((o) => `${o.method} ${o.normalized}` === `${ep.method} ${ep.normalized}`);\n      if (!wasMatchedAsPair) {\n        changes.push({ kind: 'additive', type: 'endpoint_added', endpoint: key, detail: `New endpoint ${key} is available.`, migration: 'Optional: adopt when useful.', from: null, to: key });\n      }\n    }\n  }\n  // judgment-required changes are flagged for review. Anything inferred\n  // (rename guesses, enum replacements) needs human confirmation too - only\n  // spec-explicit changes are auto-proposable.\n  const REVIEW_TYPES = new Set(['endpoint_removed', 'response_code_removed', 'security_changed', 'security_scheme_removed', 'response_field_type_changed', 'request_field_type_changed', 'param_type_changed', 'request_field_removed', 'request_field_added_required']);\n  return changes.map((c) => ({ review: REVIEW_TYPES.has(c.type) || !!c.inferred, ...c }));\n}\n\n// ---- consumer impact scan ----\n\nfunction scanConsumer(files, changes) {\n  // files: [{name, content}]. Find lines affected by each breaking change.\n  const usages = [];\n  const seen = new Set();\n  const breaking = changes.filter((c) => c.kind === 'breaking');\n  const allPaths = changes.allEndpoints || [...new Set(breaking.map((c) => endpointContext(c.endpoint)).filter(Boolean))];\n  for (const f of files) {\n    const fileEps = fileEndpointSet(f.content, allPaths);\n    const lines = f.content.split('\\n');\n    lines.forEach((text, i) => {\n      for (const c of breaking) {\n        // cross-endpoint guard: field/param/enum changes only apply to files\n        // that call that endpoint (or call no known endpoint at all)\n        const ctx = endpointContext(c.endpoint);\n        if (ctx && fileEps.size > 0 && !fileEps.has(ctx) && c.type !== 'endpoint_removed' && c.type !== 'base_path_changed' && !c.type.startsWith('security')) continue;\n        let hit = false;\n        if (c.type === 'endpoint_removed' || c.type === 'base_path_changed') {\n          const p = (c.endpoint.split(' ')[1] || '').replace(/\\{[^}]+\\}/g, '');\n          if (p && text.includes(p)) hit = true;\n        }\n        if (c.type === 'param_renamed' || c.type === 'param_removed') {\n          if (new RegExp(`['\"\\\\s{]${c.from}['\"\\\\s:]`).test(text)) hit = true;\n        }\n        if (c.type === 'response_field_renamed' || c.type === 'response_field_removed' || c.type === 'request_field_renamed' || c.type === 'request_field_removed' || c.type === 'response_field_type_changed' || c.type === 'request_field_type_changed') {\n          const leaf = leafName(c.from || c.field);\n          if (leaf && new RegExp(`[.\\\\s{'\"]${leaf}[\\\\s,}'\":]`).test(text)) hit = true;\n        }\n        if (c.type === 'enum_value_removed') {\n          if (new RegExp(`['\"\\`]${c.from}['\"\\`]`).test(text)) hit = true;\n        }\n        if (hit) {\n          const key = `${f.name}:${i + 1}:${c.type}:${c.from}`;\n          if (!seen.has(key)) { seen.add(key); usages.push({ file: f.name, line: i + 1, text: text.trimEnd(), change: c }); }\n        }\n      }\n    });\n  }\n  return usages;\n}\n\n// ---- fix generation ----\n\nfunction buildFixes(files, changes, opts = {}) {\n  const breaking = changes.filter((c) => c.kind === 'breaking');\n  const removedPaths = breaking.filter((c) => c.type === 'endpoint_removed').map((c) => c.endpoint.split(' ')[1]);\n  const fixes = [];\n  const allPaths = changes.allEndpoints || [...new Set(breaking.map((c) => endpointContext(c.endpoint)).filter(Boolean))];\n  for (const f of files) {\n    const fileEps = fileEndpointSet(f.content, allPaths);\n    const inScope = (c) => {\n      const ctx = endpointContext(c.endpoint);\n      return !ctx || fileEps.size === 0 || fileEps.has(ctx) || c.type === 'endpoint_removed' || c.type === 'base_path_changed' || c.type.startsWith('security');\n    };\n    const lines = f.content.split('\\n');\n    const edits = [];\n    const suggested = [];\n    const seenSug = new Set();\n    lines.forEach((text, i) => {\n      // Never auto-edit a line that calls a removed endpoint; manual review owns it.\n      if (removedPaths.some((p) => p && text.includes(p))) return;\n      let after = text;\n      const applied = [];\n      for (const c of breaking) {\n        if (c.type === 'base_path_changed' && c.from && c.to) {\n          // only rewrite full matched endpoint paths, never a bare version prefix:\n          // a removed sibling endpoint (e.g. /v1/charges) must stay untouched + flagged.\n          if (after.includes(c.from)) {\n            after = after.split(c.from).join(c.to);\n            applied.push(`path ${c.from} -> ${c.to}`);\n          }\n        } else if ((c.type === 'param_renamed' || c.type === 'response_field_renamed' || c.type === 'request_field_renamed') && c.from && c.to) {\n          const fromLeaf = leafName(c.from), toLeaf = leafName(c.to);\n          const re = new RegExp(`\\\\b${fromLeaf}\\\\b`, 'g');\n          if (re.test(after)) {\n            const replaced = after.replace(re, toLeaf);\n            if (!inScope(c)) { /* different endpoint - leave this line alone */ }\n            else if (c.inferred && !opts.applyInferred) {\n              const skey = `${i + 1}:${replaced}`;\n              if (!seenSug.has(skey)) { seenSug.add(skey); suggested.push({ line: i + 1, before: text, after: replaced, applied: [`inferred rename ${fromLeaf} -> ${toLeaf}`], reason: c.migration }); }\n            } else {\n              after = replaced;\n              applied.push(`rename ${fromLeaf} -> ${toLeaf}${c.inferred ? ' (inferred)' : ''}`);\n            }\n          }\n        } else if (c.type === 'enum_value_removed' && c.from && c.to) {\n          const re = new RegExp(`(['\"\\`])${c.from}\\\\1`, 'g');\n          if (re.test(after)) {\n            const replaced = after.replace(re, `$1${c.to}$1`);\n            if (!inScope(c)) { /* different endpoint */ }\n            else if (c.inferred && !opts.applyInferred) {\n              const skey = `${i + 1}:${replaced}`;\n              if (!seenSug.has(skey)) { seenSug.add(skey); suggested.push({ line: i + 1, before: text, after: replaced, applied: [`inferred enum ${c.from} -> ${c.to}`], reason: c.migration }); }\n            } else {\n              after = replaced;\n              applied.push(`enum ${c.from} -> ${c.to}${c.inferred ? ' (inferred)' : ''}`);\n            }\n          }\n        }\n      }\n      if (applied.length && !edits.some((e) => e.line === i + 1 && e.after === after)) edits.push({ line: i + 1, before: text, after, applied });\n    });\n    // manual-review flags: endpoint_removed references\n    const manual = [];\n    lines.forEach((text, i) => {\n      for (const c of breaking) {\n        if (c.type === 'endpoint_removed') {\n          const p = (c.endpoint.split(' ')[1] || '');\n          if (p && text.includes(p)) manual.push({ line: i + 1, text: text.trim(), reason: c.detail });\n        }\n      }\n    });\n    if (edits.length || manual.length || suggested.length) fixes.push({ file: f.name, edits, manual, suggested });\n  }\n  return fixes;\n}\n\nfunction buildPR({ oldVersion, newVersion, apiTitle, changes, fixes }) {\n  const breaking = changes.filter((c) => c.kind === 'breaking');\n  const additive = changes.filter((c) => c.kind === 'additive');\n  const editCount = fixes.reduce((n, f) => n + f.edits.length, 0);\n  const manualCount = fixes.reduce((n, f) => n + f.manual.length, 0);\n  const reviewCount = changes.filter((c) => c.review).length;\n  const L = [];\n  L.push(`## Migrate ${apiTitle} ${oldVersion} -> ${newVersion}`);\n  L.push('');\n  L.push(`Generated by Patchline (deterministic rules, no AI inference). ${breaking.length} breaking and ${additive.length} additive changes detected (${reviewCount} change(s) need human judgment); ${editCount} call-site edit(s) proposed, ${manualCount} code spot(s) flagged for manual review.`);\n  L.push('');\n  L.push('### Breaking changes');\n  for (const c of breaking) L.push(`- **${c.type}** (${c.endpoint}): ${c.detail} _Fix:_ ${c.migration}`);\n  if (additive.length) {\n    L.push('');\n    L.push('### Additive (no action required)');\n    for (const c of additive) L.push(`- **${c.type}** (${c.endpoint}): ${c.detail}`);\n  }\n  L.push('');\n  L.push('### Proposed edits');\n  for (const f of fixes) {\n    L.push(`#### ${f.file}`);\n    L.push('```diff');\n    for (const e of f.edits) {\n      L.push(`@@ line ${e.line} (${e.applied.join('; ')})`);\n      L.push(`- ${e.before.trim()}`);\n      L.push(`+ ${e.after.trim()}`);\n    }\n    L.push('```');\n    for (const sg of f.suggested || []) {\n      L.push('```diff');\n      L.push(`@@ line ${sg.line} INFERRED - verify before applying (${sg.applied.join('; ')})`);\n      L.push(`- ${sg.before.trim()}`);\n      L.push(`+ ${sg.after.trim()}`);\n      L.push('```');\n    }\n    for (const mn of f.manual) L.push(`- :warning: Manual review at line ${mn.line}: \\`${mn.text}\\` - ${mn.reason}`);\n  }\n  L.push('');\n  L.push('### Verification checklist');\n  L.push('- [ ] CI passes with the new API version');\n  L.push('- [ ] Contract tests cover renamed fields and enum mappings');\n  L.push('- [ ] Manual-review spots resolved or ticketed');\n  return L.join('\\n');\n}\n\nfunction summarize(changes) {\n  const breaking = changes.filter((c) => c.kind === 'breaking').length;\n  const additive = changes.filter((c) => c.kind === 'additive').length;\n  const warnings = changes.filter((c) => c.kind === 'warning').length;\n  const review = changes.filter((c) => c.review).length;\n  return { breaking, additive, warnings, review, total: changes.length };\n}\n\n// ---------- app wiring ----------\nconst FIX = JSON.parse(document.getElementById('fixtures').textContent);\nconst $ = (id) => document.getElementById(id);\nlet state = { changes: null, files: FIX.consumer, fixes: null, oldSpec: null, newSpec: null };\n\nfunction loadSample() {\n  $('specError').textContent = '';\n  $('oldSpec').value = JSON.stringify(FIX.oldSpec, null, 2);\n  $('newSpec').value = JSON.stringify(FIX.newSpec, null, 2);\n  $('oldVerLabel').textContent = FIX.oldSpec.info.title + ' v' + FIX.oldSpec.info.version;\n  $('newVerLabel').textContent = FIX.newSpec.info.title + ' v' + FIX.newSpec.info.version;\n}\nfunction toast(msg) {\n  const t = $('toast'); t.textContent = msg; t.classList.add('show');\n  setTimeout(() => t.classList.remove('show'), 1800);\n}\nfunction go(step) {\n  document.querySelectorAll('nav.steps button').forEach((b) => {\n    b.classList.toggle('on', b.dataset.step === String(step));\n    if (Number(b.dataset.step) <= step) b.disabled = false;\n  });\n  document.querySelectorAll('section').forEach((s) => s.classList.toggle('on', s.id === 's' + step));\n  window.scrollTo({ top: 0, behavior: 'smooth' });\n}\ndocument.querySelectorAll('nav.steps button').forEach((b) => b.addEventListener('click', () => { if (!b.disabled) go(b.dataset.step); }));\n$('resetSpecs').addEventListener('click', loadSample);\n\nconst SERVER = location.protocol.startsWith('http');\n\nasync function normalizeInput(text) {\n  if (!SERVER) {\n    // standalone file:// mode: JSON only, no $ref resolution (hosted app handles those)\n    return JSON.parse(text);\n  }\n  // parse in-browser when possible - the hosted worker has no parse endpoint\n  try { return JSON.parse(text); } catch { /* not JSON: try the local server's YAML parse */ }\n  const res = await fetch('/api/parse', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ text }) });\n  if (res.status === 404 || res.status === 501) throw new Error('Pasted YAML needs the local server (npm start); this hosted deployment accepts pasted JSON, or a hosted URL analysis below.');\n  const body = await res.json();\n  if (!res.ok) throw new Error(body.error || 'parse failed');\n  return body.spec;\n}\n\n$('runDiff').addEventListener('click', async () => {\n  $('specError').textContent = '';\n  try {\n    state.oldSpec = await normalizeInput($('oldSpec').value);\n    state.newSpec = await normalizeInput($('newSpec').value);\n    state.jobResult = null;\n  } catch (e) { $('specError').textContent = e.message; return; }\n  state.changes = diffSpecs(state.oldSpec, state.newSpec);\n  renderDiff();\n  go(2);\n});\n\nasync function loadUrl_into(urlInput, ta, label) {\n  const url = $(urlInput).value.trim();\n  if (!url) return;\n  if (!SERVER) { $('specError').textContent = 'Loading from a URL needs the hosted app (the standalone page cannot make network calls).'; return; }\n  $('specError').textContent = 'Loading ' + url + ' ...';\n  try {\n    const res = await fetch('/api/fetch-spec', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ url }) });\n    const body = await res.json();\n    if (!res.ok) throw new Error(body.error || 'fetch failed');\n    if (body.text === null) { $('specError').textContent = 'Not modified (the server already has this version cached); reload the page to re-fetch.'; return; }\n    $(ta).value = body.text;\n    try {\n      const doc = JSON.parse(body.text);\n      if (doc.info) $(label).textContent = doc.info.title + ' v' + doc.info.version;\n    } catch { /* YAML: label set after parse */ }\n    $('specError').textContent = '';\n  } catch (e) { $('specError').textContent = e.message; }\n}\n$('loadOldUrl').addEventListener('click', () => loadUrl_into('oldUrl', 'oldSpec', 'oldVerLabel'));\n$('loadNewUrl').addEventListener('click', () => loadUrl_into('newUrl', 'newSpec', 'newVerLabel'));\n\nfunction renderDiff() {\n  const s = summarize(state.changes);\n  $('statRow').innerHTML =\n    `<div class=\"stat break\"><div class=\"v\">${s.breaking}</div><div class=\"k\">breaking</div></div>` +\n    `<div class=\"stat add\"><div class=\"v\">${s.additive}</div><div class=\"k\">additive</div></div>` +\n    `<div class=\"stat warn\"><div class=\"v\">${s.warnings}</div><div class=\"k\">warnings</div></div>` +\n    `<div class=\"stat warn\"><div class=\"v\">${s.review}</div><div class=\"k\">need human judgment</div></div>`;\n  const tb = document.querySelector('#changeTable tbody');\n  tb.innerHTML = '';\n  for (const c of state.changes) {\n    const tr = document.createElement('tr');\n    const pillClass = c.kind === 'breaking' ? 'break' : (c.kind === 'warning' ? 'warn' : 'add');\n    const reviewBadge = c.review ? ' <span class=\"pill review\">manual review</span>' : '';\n    tr.innerHTML = `<td><span class=\"pill ${pillClass}\">${c.kind}</span>${reviewBadge}</td>` +\n      `<td><span class=\"inline-code\">${c.type}</span></td>` +\n      `<td>${c.detail}<div class=\"mig\">&rarr; ${c.migration}</div></td>`;\n    tb.appendChild(tr);\n  }\n}\n\n$('toImpact').addEventListener('click', () => {\n  if (state.jobResult) { renderJobImpact(); go(3); return; }\n  state.fixes = buildFixes(state.files, state.changes, { applyInferred: $('applyInferred').checked });\n  renderImpact();\n  go(3);\n});\nfunction renderJobImpact() {\n  const box = $('impactList'); box.innerHTML = '';\n  const im = state.jobResult.impact;\n  if (!im) { box.innerHTML = '<p style=\"color:var(--dim)\">This job ran without a consumer repo - diff only. Add a consumer repo URL in step 01 for impact analysis.</p>'; return; }\n  const head = document.createElement('p');\n  head.style.cssText = 'color:var(--dim);font-size:13.5px;margin-bottom:14px';\n  head.textContent = 'Scanned ' + im.scannedFiles + ' file(s) in ' + im.repoUrl + ': ' + im.affectedLines + ' affected line(s), ' + im.proposedEdits + ' mechanical edit(s), ' + im.inferredSuggestions + ' inferred suggestion(s), ' + im.manualSpots + ' manual-review spot(s). Per-file edits are in the PR draft (step 04).';\n  box.appendChild(head);\n  if (im.usages && im.usages.length) {\n    const t = document.createElement('table');\n    t.innerHTML = '<thead><tr><th style=\"width:70%\">File</th><th>Line</th></tr></thead>';\n    const tb = document.createElement('tbody');\n    for (const u of im.usages) {\n      const tr = document.createElement('tr');\n      tr.innerHTML = '<td><span class=\"inline-code\">' + esc(u.file) + '</span></td><td>' + u.line + '</td>';\n      tb.appendChild(tr);\n    }\n    t.appendChild(tb); box.appendChild(t);\n  }\n}\n\n$('applyInferred').addEventListener('change', () => {\n  if (!state.changes) return;\n  state.fixes = buildFixes(state.files, state.changes, { applyInferred: $('applyInferred').checked });\n  renderImpact();\n});\n\nfunction esc(s) { return s.replace(/&/g, '&amp;').replace(/</g, '&lt;'); }\n\nfunction renderImpact() {\n  const box = $('impactList'); box.innerHTML = '';\n  const usages = scanConsumer(state.files, state.changes);\n  const byFile = new Set(usages.map((u) => u.file));\n  if (!state.fixes.length) { box.innerHTML = '<p style=\"color:var(--dim)\">No call sites affected. This consumer is already compatible.</p>'; return; }\n  for (const f of state.fixes) {\n    const div = document.createElement('div');\n    div.className = 'file-block';\n    let inner = `<div class=\"file-head\"><span>${f.file}</span><span class=\"counts\">${f.edits.length} edit(s) &middot; ${(f.suggested || []).length} inferred &middot; ${f.manual.length} manual</span></div>`;\n    if (f.edits.length) {\n      inner += '<pre class=\"diff\">';\n      for (const e of f.edits) {\n        inner += `<span class=\"meta\">@@ line ${e.line} - ${esc(e.applied.join('; '))}</span>`;\n        inner += `<span class=\"del\">- ${esc(e.before.trim())}</span>`;\n        inner += `<span class=\"addline\">+ ${esc(e.after.trim())}</span>`;\n      }\n      inner += '</pre>';\n    }\n    for (const sg of (f.suggested || [])) {\n      inner += `<div class=\"manual-item\">&#9888; Inferred suggestion (verify before applying), line ${sg.line}:<br><code>- ${esc(sg.before.trim())}</code><br><code>+ ${esc(sg.after.trim())}</code><br><span style=\"color:var(--dim);font-size:12.5px\">${esc(sg.reason)}</span></div>`;\n    }\n    for (const mn of f.manual) {\n      inner += `<div class=\"manual-item\">&#9888; Manual review, line ${mn.line}: <code>${esc(mn.text)}</code><br><span style=\"color:var(--dim);font-size:12.5px\">${esc(mn.reason)}</span></div>`;\n    }\n    div.innerHTML = inner;\n    box.appendChild(div);\n  }\n  const untouched = state.files.filter((f) => !byFile.has(f.name));\n  if (untouched.length) {\n    const p = document.createElement('p');\n    p.style.cssText = 'color:var(--faint);font-size:13px;margin-top:6px';\n    p.textContent = 'Untouched by breaking changes: ' + untouched.map((f) => f.name).join(', ');\n    box.appendChild(p);\n  }\n}\n\n$('toPR').addEventListener('click', () => {\n  if (state.jobResult) {\n    $('prOut').textContent = (state.jobResult.impact && state.jobResult.impact.pr) || 'No PR draft: this job ran without a consumer repo (diff only).';\n    go(4); return;\n  }\n  const pr = buildPR({\n    oldVersion: state.oldSpec.info.version, newVersion: state.newSpec.info.version,\n    apiTitle: state.oldSpec.info.title, changes: state.changes, fixes: state.fixes,\n  });\n  $('prOut').textContent = pr;\n  go(4);\n});\n\n$('copyPR').addEventListener('click', async () => {\n  try { await navigator.clipboard.writeText($('prOut').textContent); toast('PR markdown copied'); }\n  catch { toast('Copy blocked by browser - select the text manually'); }\n});\n// ---- watch tab (hosted mode only) ----\nif (SERVER) {\n  $('watchTab').style.display = '';\n  if (window.__PATCHLINE_STATIC__) { const r = $('addWatchRow'); if (r) r.style.display = 'none'; }\n  $('modeNote').textContent = 'Hosted mode: you can paste YAML, load specs from URLs, and set up live watches (step 05).';\n  fetch('/api/health').then((r) => r.json()).then((h) => {\n    if (!h || !h.hosted) return;\n    document.body.dataset.mode = 'worker';\n    $('hostedBox').style.display = '';\n    $('modeNote').textContent = 'Hosted mode: paste JSON specs and diff in-browser, or run a hosted URL analysis below (specs fetched and consumer repo scanned as a background job). YAML paste needs the local server.';\n  }).catch(() => {});\n} else {\n  $('modeNote').textContent = 'Standalone mode: paste JSON specs. The hosted app adds YAML, URL loading and live watches.';\n}\n\nasync function refreshWatches() {\n  if (!SERVER) return;\n  const [{ watches, minIntervalMinutes }, { events }] = await Promise.all([\n    fetch('/api/watches').then((r) => r.json()),\n    fetch('/api/events').then((r) => r.json()),\n  ]);\n  $('minInt').textContent = minIntervalMinutes;\n  const tb = document.querySelector('#watchTable tbody');\n  tb.innerHTML = '';\n  for (const w of watches) {\n    const tr = document.createElement('tr');\n    tr.innerHTML = `<td><b>${esc(w.name)}</b></td><td><span class=\"inline-code\">${esc(w.url)}</span></td>` +\n      `<td>${w.intervalMinutes}m</td><td>${w.lastCheckAt ? new Date(w.lastCheckAt).toLocaleString() : 'never'}</td>` +\n      `<td>${esc(w.lastResult || '-')}</td>` +\n      ((window.__PATCHLINE_STATIC__ || document.body.dataset.mode === 'worker') ? `<td><span style=\"color:#9da7b3\">read-only (no scheduler)</span></td>` :\n      `<td><button class=\"btn ghost\" data-check=\"${w.id}\">Check now</button> <button class=\"btn ghost\" data-del=\"${w.id}\">Delete</button></td>`);\n    tb.appendChild(tr);\n  }\n  tb.querySelectorAll('[data-check]').forEach((b) => b.addEventListener('click', async () => {\n    b.disabled = true;\n    await fetch('/api/watches/check', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ id: b.dataset.check }) });\n    await refreshWatches();\n  }));\n  tb.querySelectorAll('[data-del]').forEach((b) => b.addEventListener('click', async () => {\n    await fetch('/api/watches?id=' + b.dataset.del, { method: 'DELETE' });\n    await refreshWatches();\n  }));\n  const el = $('eventList');\n  el.innerHTML = events.length ? '' : '<p class=\"hint\">No change events recorded yet.</p>';\n  for (const ev of events) {\n    const d = document.createElement('div');\n    d.className = 'file-block';\n    let impactLine = '';\n    if (ev.impact && !ev.impact.error) {\n      impactLine = `<div class=\"manual-item\">Consumer impact (${esc(ev.impact.repoUrl)}): ${ev.impact.affectedLines} affected line(s) across ${ev.impact.scannedFiles} scanned file(s) &middot; ${ev.impact.proposedEdits} edits &middot; ${ev.impact.inferredSuggestions} inferred &middot; ${ev.impact.manualSpots} manual</div>`;\n    } else if (ev.impact && ev.impact.error) {\n      impactLine = `<div class=\"manual-item\">Consumer impact failed: ${esc(ev.impact.error)}</div>`;\n    }\n    d.innerHTML = `<div class=\"file-head\"><span><b>${esc(ev.watchName)}</b> &middot; ${new Date(ev.at).toLocaleString()} &middot; v${esc(ev.oldVersion || '?')} &rarr; v${esc(ev.newVersion || '?')}</span>` +\n      `<span class=\"counts\">${ev.summary.breaking} breaking &middot; ${ev.summary.additive} additive &middot; ${ev.summary.warnings} warnings &middot; ${ev.summary.review} need review</span></div>${impactLine}`;\n    el.appendChild(d);\n  }\n}\n\n// ---- hosted background-job analysis (worker mode) ----\nlet jobPoll = null;\nconst runJobBtn = $('runJob');\nif (runJobBtn) runJobBtn.addEventListener('click', async () => {\n  const oldUrl = $('jobOldUrl').value.trim();\n  const newUrl = $('jobNewUrl').value.trim();\n  const repoUrl = $('jobRepoUrl').value.trim();\n  const st = $('jobStatus');\n  st.style.color = 'var(--dim)';\n  if (!oldUrl || !newUrl) { st.textContent = 'Both spec URLs are required.'; st.style.color = 'var(--break)'; return; }\n  st.textContent = 'Dispatching job...';\n  try {\n    const res = await fetch('/api/jobs', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(repoUrl ? { oldUrl, newUrl, repoUrl } : { oldUrl, newUrl }) });\n    const body = await res.json();\n    if (!res.ok) throw new Error(body.error || ('dispatch failed (' + res.status + ')'));\n    if (body.deduped) st.textContent = 'Identical inputs were already analyzed' + (body.originalRunAt ? ' at ' + new Date(body.originalRunAt).toLocaleString() : '') + ' - showing that result. Resubmit after the 1h dedupe window for a fresh run (mutable branch URLs are re-fetched then).';\n    pollJob(body.job_id);\n  } catch (e) { st.textContent = e.message; st.style.color = 'var(--break)'; }\n});\nasync function pollJob(id) {\n  const st = $('jobStatus');\n  clearInterval(jobPoll);\n  const started = Date.now();\n  jobPoll = setInterval(async () => {\n    if (Date.now() - started > 10 * 60 * 1000) { clearInterval(jobPoll); st.textContent = 'Timed out waiting for job ' + id.slice(0, 8) + '.'; st.style.color = 'var(--break)'; return; }\n    try {\n      const res = await fetch('/api/jobs/' + id);\n      const body = await res.json();\n      if (!res.ok) throw new Error(body.error || 'status check failed');\n      if (body.status === 'done') {\n        clearInterval(jobPoll);\n        st.textContent = 'Job ' + id.slice(0, 8) + ' done.';\n        state.jobResult = body.result || {};\n        state.oldSpec = null; state.newSpec = null;\n        state.changes = state.jobResult.changes || [];\n        renderDiff();\n        go(2);\n        toast('Hosted analysis complete');\n      } else if (body.status === 'error') {\n        clearInterval(jobPoll);\n        st.textContent = 'Job failed: ' + (body.error || 'unknown error');\n        st.style.color = 'var(--break)';\n      } else {\n        st.textContent = 'Job ' + id.slice(0, 8) + ' ' + (body.status || 'pending') + '... (' + Math.round((Date.now() - started) / 1000) + 's)';\n      }\n    } catch (e) { clearInterval(jobPoll); st.textContent = e.message; st.style.color = 'var(--break)'; }\n  }, 4000);\n}\n\n$('addWatch').addEventListener('click', async () => {\n  $('watchError').textContent = '';\n  const body = { name: $('wName').value.trim(), url: $('wUrl').value.trim(), intervalMinutes: Number($('wInt').value) || undefined };\n  const res = await fetch('/api/watches', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) });\n  const out = await res.json();\n  if (!res.ok) { $('watchError').textContent = out.error || 'failed'; return; }\n  $('wName').value = ''; $('wUrl').value = ''; $('wInt').value = '';\n  toast(out.baseline === 'baseline' ? 'Watch added, baseline saved' : 'Watch added');\n  await refreshWatches();\n});\n\nconst origGo = go;\ngo = function (step) { origGo(step); if (String(step) === '5') refreshWatches(); };\n\nfunction download(name, text, type) {\n  const a = document.createElement('a');\n  a.href = URL.createObjectURL(new Blob([text], { type }));\n  a.download = name; a.click();\n  setTimeout(() => URL.revokeObjectURL(a.href), 4000);\n}\n$('dlPR').addEventListener('click', () => download('patchline-migration-pr.md', $('prOut').textContent, 'text/markdown'));\n$('dlJSON').addEventListener('click', () => download('patchline-analysis.json', JSON.stringify({ changes: state.changes, fixes: state.fixes }, null, 2), 'application/json'));\n\nloadSample();\n</script>\n</body>\n</html>\n";

const enc = new TextEncoder();
const eq = (a, b) => {
  a = String(a || ''); b = String(b || '');
  if (a.length !== b.length) return false;
  let d = 0; for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return d === 0;
};
const json = (code, body, extra = {}) =>
  new Response(JSON.stringify(body), { status: code, headers: { 'content-type': 'application/json', ...extra } });
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const MAX_URL_LEN = 2048;
const validSpecUrl = (u) => {
  if (typeof u !== 'string' || !u.length || u.length > MAX_URL_LEN) return false;
  try { return new URL(u).protocol === 'https:'; } catch { return false; }
};

async function gh(env, path, opts = {}) {
  const base = env.GITHUB_API_BASE || 'https://api.github.com';
  const res = await fetch(base + path, {
    ...opts,
    headers: {
      authorization: 'Bearer ' + env.GITHUB_DISPATCH_PAT,
      accept: 'application/vnd.github+json',
      'x-github-api-version': '2022-11-28',
      'user-agent': 'patchline-worker',
      ...(opts.headers || {}),
    },
  });
  return res;
}

async function readBranchJson(env, path) {
  const cached = await env.JOBS.get('cache:' + path, 'json');
  if (cached) return { status: 200, body: cached };
  const res = await gh(env, `/repos/${env.GITHUB_REPO}/contents/${path}?ref=patchline-data`);
  if (res.status !== 200) return { status: res.status, body: null };
  const meta = await res.json();
  const body = JSON.parse(atob(meta.content.replace(/\n/g, '')));
  await env.JOBS.put('cache:' + path, JSON.stringify(body), { expirationTtl: 60 });
  return { status: 200, body };
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const p = url.pathname;

    if (p === '/' || p === '/index.html') {
      return new Response(UI_HTML, { headers: { 'content-type': 'text/html; charset=utf-8' } });
    }
    if (p === '/api/health') return json(200, { ok: true, hosted: true });

    // The static snapshot (baked private state) is served ONLY behind the
    // gate, from KV (written at deploy time). The openly served UI shell
    // above never contains baked state.
    if (p === '/snapshot') {
      if (!eq(request.headers.get('x-patchline-key'), env.PATCHLINE_AUTH_KEY)) {
        return json(401, { error: 'unauthorized' });
      }
      const html = await env.JOBS.get('snapshot:index.html');
      if (!html) return json(404, { error: 'no snapshot published yet' });
      return new Response(html, { headers: { 'content-type': 'text/html; charset=utf-8', 'x-robots-tag': 'noindex' } });
    }

    // every other /api route is behind the shared-secret gate
    if (!eq(request.headers.get('x-patchline-key'), env.PATCHLINE_AUTH_KEY)) {
      return json(401, { error: 'unauthorized' });
    }

    if (p === '/api/watches' && request.method === 'GET') {
      const r = await readBranchJson(env, 'watches.json');
      return r.status === 200 ? json(200, { watches: r.body, minIntervalMinutes: 60 }) : json(r.status === 404 ? 200 : 502, { watches: [], note: 'no hosted state yet' });
    }
    if (p === '/api/events' && request.method === 'GET') {
      const r = await readBranchJson(env, 'events.json');
      return r.status === 200 ? json(200, { events: r.body }) : json(r.status === 404 ? 200 : 502, { events: [], note: 'no hosted state yet' });
    }

    if (p === '/api/jobs' && request.method === 'POST') {
      let body;
      try { body = await request.json(); } catch { return json(400, { error: 'invalid JSON body' }); }
      if (JSON.stringify(body).length > 8192) return json(413, { error: 'payload too large' });
      if (!validSpecUrl(body.oldUrl) || !validSpecUrl(body.newUrl)) return json(400, { error: 'oldUrl and newUrl must be https URLs' });
      if (body.repoUrl != null && (typeof body.repoUrl !== 'string' || body.repoUrl.length > MAX_URL_LEN || !body.repoUrl.startsWith('https://github.com/'))) {
        return json(400, { error: 'repoUrl must be a https://github.com/ repository' });
      }
      // global rate limit behind the gate: N jobs per rolling hour
      const limit = Number(env.RATE_LIMIT_PER_HOUR || 10);
      const bucket = 'rate:' + new Date().toISOString().slice(0, 13);
      const used = (await env.JOBS.get(bucket, 'json')) || 0;
      if (used >= limit) return json(429, { error: 'hourly job limit reached', limit });
      // dedupe identical in-flight requests by payload hash
      const hashBuf = await crypto.subtle.digest('SHA-256', enc.encode([body.oldUrl, body.newUrl, body.repoUrl || ''].join('\n')));
      const hash = [...new Uint8Array(hashBuf)].map((b) => b.toString(16).padStart(2, '0')).join('');
      const existing = await env.JOBS.get('dedupe:' + hash, 'json');
      if (existing) return json(200, { job_id: existing.job_id, status: existing.status, deduped: true, originalRunAt: existing.at || null, note: 'Identical inputs were already submitted within the last hour; this is the original run. Mutable URLs (branch heads) are re-fetched on a fresh submission after the 1h dedupe window.' });

      const job = { job_id: crypto.randomUUID(), type: 'analyze', oldUrl: body.oldUrl, newUrl: body.newUrl };
      if (body.repoUrl) job.repoUrl = body.repoUrl;
      const res = await gh(env, `/repos/${env.GITHUB_REPO}/actions/workflows/job.yml/dispatches`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ ref: 'main', inputs: { payload: JSON.stringify(job) } }),
      });
      if (res.status !== 204) return json(502, { error: 'dispatch failed', upstream: res.status });
      const rec = { job_id: job.job_id, status: 'dispatched', at: new Date().toISOString() };
      await env.JOBS.put('job:' + job.job_id, JSON.stringify(rec), { expirationTtl: 86400 });
      await env.JOBS.put('dedupe:' + hash, JSON.stringify(rec), { expirationTtl: 3600 });
      await env.JOBS.put(bucket, JSON.stringify(used + 1), { expirationTtl: 3700 });
      return json(202, rec);
    }

    const m = p.match(/^\/api\/jobs\/([0-9a-f-]{36})$/);
    if (m && request.method === 'GET') {
      if (!UUID_RE.test(m[1])) return json(400, { error: 'bad job id' });
      const r = await readBranchJson(env, `jobs/${m[1]}.json`);
      if (r.status === 200) return json(200, r.body);
      const rec = await env.JOBS.get('job:' + m[1], 'json');
      if (rec) return json(200, { job_id: m[1], status: 'pending', dispatchedAt: rec.at });
      return json(404, { error: 'unknown job id' });
    }

    return json(404, { error: 'not found' });
  },
};
